-- =====================================================================
-- EXPECTED VALUES (DDS-14 §9; re-derived in Python — TEST-14 TC-005)
-- =====================================================================
\echo '=== Appendix A (J1) — the two-part rendering (AC-04, AC-08) ==='
SELECT genba.render_text((SELECT id FROM genba.segment WHERE job_id = 'f0000000-0000-4000-8000-000000000001' AND ordinal = 1));
\echo 'expected: SOURCE (JA) / TRANSLATION (TH) หลังจากเปลี่ยนเงื่อนไขการขึ้นรูป อัตราของเสียเพิ่มขึ้น; then a ruled INTERPRETATION (inferred — confidence 0.91) block: injection_molding / problem_report / entities {"metric": ["不良率"], "direction": "up", "parameter": ["成形条件"]} / timing "sequence stated: the change precedes the increase (causal claim implied, not verified)" / 5 checks (Melt / mould temperature … Material condition) / 4 related documents (Control plan, FMEA, Past case #178, SPC chart) / Glossary terms applied: 不良率, 成形条件'
\echo '=== J1 checks and interpretation ==='
SELECT s.status, s.tm_score, s.checks_json ->> 'clean' AS clean, i.confidence, i.ambiguous, i.process, i.message_type, i.entities_json, jsonb_array_length(i.suggested_checks_json) AS checks, jsonb_array_length(i.related_docs_json) AS docs
  FROM genba.segment s JOIN genba.interpretation i ON i.segment_id = s.id WHERE s.job_id = 'f0000000-0000-4000-8000-000000000001';
\echo 'expected: approved, tm_score NULL, clean true, 0.910, false, injection_molding, problem_report, entities as above, 5, 4'
\echo '=== AC-07: J2 exact TM reuse ==='
SELECT s.tm_score, m.method, s.mt_text = t.tgt_text AS verbatim, t.doc_ref FROM genba.segment s JOIN genba.tm_match m ON m.segment_id = s.id JOIN knowledge.tm_segment t ON t.id = m.tm_segment_id WHERE s.job_id = 'f0000000-0000-4000-8000-000000000003';
\echo 'expected: 1.000, exact, true, doc_ref job:f0000000-0000-4000-8000-000000000001#1'
\echo '=== J3 — the 8D (AC-02, AC-03, omission, fuzzy, edits) ==='
SELECT ordinal, status, (checks_json ->> 'blocked')::boolean AS blocked, (checks_json ->> 'flagged')::boolean AS flagged, edit_distance, tm_written_id IS NOT NULL AS in_tm FROM genba.segment WHERE job_id = 'f0000000-0000-4000-8000-000000000004' ORDER BY ordinal;
\echo 'expected: 1..11 approved (blocked false, flagged false, in_tm true), 12 needs_review; edit_distance on 3 = 0.0588, 4 = 0.1176, 5 = 0.5417'
SELECT ordinal, before_text, after_text, edit_distance FROM genba.segment_edit e JOIN genba.segment s ON s.id = e.segment_id WHERE s.job_id = 'f0000000-0000-4000-8000-000000000004' ORDER BY ordinal;
\echo 'expected: 3 edits — 3.5 mm → 3.2 mm; 修正措置 → 是正処置; one sentence → two sentences'
SELECT s.ordinal, m.method, m.score FROM genba.tm_match m JOIN genba.segment s ON s.id = m.segment_id WHERE s.job_id = 'f0000000-0000-4000-8000-000000000004' ORDER BY s.ordinal;
\echo 'expected: ordinal 6 trigram 0.921 (>= 0.85, offered with a diff, not applied)'
SELECT genba.codes_preserved('ค่าพิกัดความคลาดเคลื่อน ±0.05 mm ความหนา 3.2 mm ล็อต LOT-2609-114', '公差 ±0.05 mm、厚さ 3.2 mm、ロット LOT-2609-114') AS ac02, genba.codes_preserved('ค่าที่วัดได้ 3.2 mm เกินพิกัดความคลาดเคลื่อน', '測定値 3.5 mm が公差を超過') AS blocked_mt;
\echo 'expected: ac02 ok true source ["3.2mm","LOT-2609-114","±0.05mm"]; blocked_mt ok false missing ["3.2mm"] extra ["3.5mm"]'
SELECT genba.glossary_hits('มาตรการแก้ไข: เปลี่ยนแม่พิมพ์และตรวจสอบซ้ำ', '修正措置: 金型を交換し再検査する', 'th', 'ja') AS ac03;
\echo 'expected: applied [金型, 検査] missing [是正処置] forbidden [{term 是正処置, rendering 修正措置, mandated 是正処置}]'
\echo '=== AC-06: J4 OCR regions ==='
SELECT * FROM genba.v_ocr_flags WHERE job_id = 'f0000000-0000-4000-8000-000000000005' ORDER BY ordinal;
\echo 'expected: regions 1-3 vertical printed (0.981 / 0.972 / 0.966, low_confidence false), region 4 horizontal handwriting 0.712 low_confidence true; every region linked to a segment'
\echo '=== AC-05: J5 readings ==='
SELECT i.confidence, i.ambiguous, i.process, i.message_type, (SELECT count(*) FROM genba.reading r WHERE r.segment_id = i.segment_id) AS readings FROM genba.interpretation i JOIN genba.segment s ON s.id = i.segment_id WHERE s.job_id = 'f0000000-0000-4000-8000-000000000006';
\echo 'expected: 0.550, true, NULL, NULL, 3'
\echo '=== J6 batch progress (FR-20, NFR-07) ==='
SELECT status, files, files_done, files_failed, resumed_from_ordinal, segment_count, done_count FROM genba.v_job_progress WHERE id = 'f0000000-0000-4000-8000-000000000007';
\echo 'expected: done, 5, 5, 0, 4, 4, 4'
\echo '=== glossary versions (NFR-08) ==='
SELECT ja, version_no, effective_from, aliases FROM genba.v_glossary_current WHERE ja IN ('是正処置', '成形条件', 'キズ') ORDER BY ja;
\echo 'expected: キズ v1 2026-09-01 alias 傷 (ja); 成形条件 v1 alias 成条 (ja), สภาพการฉีด (th); 是正処置 v2 2026-10-01 alias CA (en)'
\echo '=== TM stats, consistency, candidates, usage ==='
SELECT * FROM genba.v_tm_stats ORDER BY src_lang, tgt_lang;
\echo 'expected: ja→en 11 (10 + J1E), ja→th 26 (25 + J1), th→ja 16 (5 + 11 from the 8D)'
SELECT ja, segments, consistent, inconsistent FROM genba.v_term_consistency WHERE ja IN ('不良率', '是正処置', '金型') ORDER BY ja;
SELECT ja, occurrences, status FROM genba.term_candidate ORDER BY occurrences DESC, ja;
SELECT g.ja, u.count, u.inconsistencies FROM genba.term_usage u JOIN knowledge.glossary_term g ON g.id = u.term_id WHERE u.usage_date = '2026-09-22' ORDER BY g.ja;
\echo '=== evaluation gate (AI-02, AI-05, AI-08) ==='
SELECT version, run_at, prompt_version, glossary_compliance, numbers_preserved, mean_ped, class_accuracy, passed, investigate FROM genba.v_eval_gate ORDER BY run_at;
\echo 'expected: run 1 1.0000 / 1.0000 / 0.1485 / 0.9250 passed true investigate false; run 2 1.0000 / 1.0000 / 0.1388 / 0.9250 passed true investigate false; run 3 1.0000 / 1.0000 / 0.1885 / 0.9250 passed true investigate TRUE (PED +0.04 > 2 %)'
SELECT count(*) AS rule_pred_mismatch FROM genba.eval_result x JOIN genba.test_segment t ON t.id = x.test_segment_id WHERE (SELECT c.process FROM genba.classify(t.src_text) c) IS DISTINCT FROM x.process_pred OR (SELECT c.message_type FROM genba.classify(t.src_text) c) IS DISTINCT FROM x.message_pred;
\echo 'expected: 0 (the stored predictions are the rule classifier''s own)'
\echo '=== quality dashboard (FR-31) ==='
SELECT * FROM genba.v_quality_dashboard ORDER BY day, src_lang, tgt_lang;
\echo 'expected: 2026-09-22 ja→en 1 segment, ja→th 1, th→ja 11 (mean PED over the 11 = (0.0588 + 0.1176 + 0.5417) / 11), glossary compliance 1.0000'
\echo '=== counts ==='
SELECT (SELECT count(*) FROM genba.translation_job) AS jobs, (SELECT count(*) FROM genba.segment) AS segments, (SELECT count(*) FROM genba.segment WHERE status = 'approved') AS approved,
       (SELECT count(*) FROM knowledge.tm_segment) AS tm, (SELECT count(*) FROM genba.tm_index) AS tm_index, (SELECT count(*) FROM genba.interpretation) AS interpretations,
       (SELECT count(*) FROM genba.reading) AS readings, (SELECT count(*) FROM genba.ocr_region) AS ocr_regions, (SELECT count(*) FROM genba.segment_edit) AS edits,
       (SELECT count(*) FROM genba.term_version) AS term_versions, (SELECT count(*) FROM genba.eval_result) AS eval_results;
\echo 'expected: jobs 9, segments 28, approved 13, tm 53, tm_index 53, interpretations 5, readings 3, ocr_regions 7, edits 3, term_versions 31, eval_results 120'

